// ra-markdown exposed names (from when we used toast-ui) => Crepe top bar keys. indent, outdent and scrollSync have no Crepe equivalent.
const toolbarItemKeys = {
    heading: 'heading-selector',
    bold: 'bold',
    italic: 'italic',
    strike: 'strikethrough',
    code: 'code',
    ul: 'bullet-list',
    ol: 'ordered-list',
    task: 'task-list',
    link: 'link',
    image: 'image',
    table: 'table',
    codeblock: 'code-block',
    quote: 'quote',
    hr: 'hr',
};
// Replaces the default Crepe top bar groups with the toolbarItems groups
export const buildToolbar = (toolbarItems) => (builder) => {
    const builtins = builder.build().flatMap(group => group.items);
    builder.clear();
    toolbarItems.forEach((items, index) => {
        const group = builder.addGroup(`group-${index}`, '');
        items.forEach(item => {
            if (typeof item !== 'string') {
                group.addItem(item.name, {
                    icon: item.icon,
                    onRun: item.onClick,
                    active: item.active ?? (() => false),
                });
                return;
            }
            // missing when its Crepe feature is disabled (image, table)
            const builtin = builtins.find(({ key }) => key === toolbarItemKeys[item]);
            if (builtin)
                group.addItem(builtin.key, builtin);
        });
    });
};
