export const markdownFontFamily = "'Open Sans', 'Helvetica Neue', 'Helvetica', 'Arial', 'Nanum Barun Gothic', 'Malgun Gothic', sans-serif";
export const markdownCodeFontFamily = "Consolas, Courier, 'Lucida Grande', 'Apple SD Gothic Neo', 'Malgun Gothic', 'Segoe UI', sans-serif";
